const crypto = require('crypto');
const SECRET_KEY = 'fathimk666';
const inputData = $input.first().json;
const headers = inputData.headers;
const authHeader = headers.authorization || headers.Authorization;

if (!authHeader || !authHeader.startsWith('Bearer ')) {
  return { json: { authorized: false, error: 'Missing or invalid Authorization header' } };
}

const token = authHeader.split(' ')[1];

try {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('Invalid JWT structure');

  const [headerB64, payloadB64, signatureB64] = parts;
  const signatureInput = `${headerB64}.${payloadB64}`;
  const hmac = crypto.createHmac('sha256', SECRET_KEY);
  hmac.update(signatureInput);
  const calculatedSignature = hmac.digest('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

  if (calculatedSignature !== signatureB64) {
    return { json: { authorized: false, error: 'Invalid signature' } };
  }

  let paddedPayload = payloadB64.replace(/-/g, '+').replace(/_/g, '/');
  while (paddedPayload.length % 4) paddedPayload += '=';
  const payload = JSON.parse(Buffer.from(paddedPayload, 'base64').toString('utf-8'));

  if (payload.exp && Math.floor(Date.now() / 1000) > payload.exp) {
    return { json: { authorized: false, error: 'Token expired' } };
  }

  return { json: { authorized: true, payload, body: inputData.body } };
} catch (error) {
  return { json: { authorized: false, error: error.message } };
}

const rawText = $input.first().json.data || "";
const extract = (pattern) => { const match = rawText.match(pattern); return match ? match[1].trim() : null; };

const titleFull = extract(/Title:\s*(.+)/) || "Job Application";
const url = extract(/URL Source:\s*(.+)/);
const splitContent = rawText.split("Markdown Content:");
let markdownContent = splitContent.length > 1 ? splitContent[1] : rawText;
markdownContent = markdownContent.trim();

let companyName = "Hiring Team";
const companyMatch = markdownContent.match(/^([A-Z][a-zA-Z0-9\s&]+?)\s+(is a|is the|is an|founded in)/);
if (companyMatch) companyName = companyMatch[1].trim();

return [{ json: { meta: { role_title: titleFull, company_name: companyName, url: url, scraped_date: new Date().toISOString() }, content: { full_raw_text: markdownContent } } }];

