// ═══════════════════════════════════════════════════════════
// N8N CLEANUP NODE — Bulletproof LaTeX sanitizer for XeLaTeX
// ═══════════════════════════════════════════════════════════

const rawOutput = $('Gemini - Tailor CV').first().json.content.parts[0].text;
const startTag = "<<<LATEX_START>>>";
const endTag   = "<<<LATEX_END>>>";

let latexCode = "";
const startIndex = rawOutput.indexOf(startTag);
const endIndex   = rawOutput.indexOf(endTag);
if (startIndex !== -1 && endIndex !== -1) {
    latexCode = rawOutput.substring(startIndex + startTag.length, endIndex).trim();
} else {
    latexCode = rawOutput.replace(/```latex/gi, '').replace(/```/g, '').trim();
}

// ─── EXTRACT JOB TITLE before any LaTeX processing ──────────
// The Gemini output has a comment line: % ===== TAILORED CV: JOB TITLE @ COMPANY =====
// This is the most reliable source — no LaTeX parsing needed.
let jobTitle = 'Cybersecurity Engineer';

// Method 1: from the delimiter comment the AI always writes
const commentMatch = rawOutput.match(/TAILORED CV[:\s-]+(.+?)\s*@\s*(.+?)\s*={3}/i)
                  || latexCode.match(/TAILORED CV[:\s-]+(.+?)\s*@/i);
if (commentMatch && commentMatch[1]) {
    const candidate = commentMatch[1].trim().replace(/%/g, '').trim();
    if (candidate.length >= 3) jobTitle = candidate;
}

// Method 2 fallback: look for the subtitle fontsize block in the AI's header
// ONLY match content that is NOT a LaTeX color name (no uppercase-only words)
if (jobTitle === 'Cybersecurity Engineer') {
    const subtitleMatch = latexCode.match(
        /\\fontsize\{(?:9|10|10\.\d+|11)\}[^}]*\}\\selectfont[^{]{0,40}\\color\{[^}]+\}([^}\\%\n]{6,80})\}/
    );
    if (subtitleMatch && subtitleMatch[1]) {
        const candidate = subtitleMatch[1].trim();
        // Reject if it looks like a LaTeX identifier (camelCase color names like headerFG)
        // Real titles have spaces and mixed case words like "Cybersecurity Engineer"
        const hasSpace = candidate.includes(' ');
        const isLatexId = /^[a-zA-Z]+[A-Z][a-zA-Z]*$/.test(candidate); // camelCase = LaTeX id
        if (hasSpace && !isLatexId && candidate.length >= 6) {
            jobTitle = candidate;
        }
    }
}

// ─── FIX 1: Strip magic comment ─────────────────────────────
latexCode = latexCode.replace(/^%!TEX[^\n]*\n/m, '');

// ─── FIX 2: Nuclear preamble replacement ────────────────────
const knownGoodPreamble = `\\documentclass[10pt,a4paper]{article}

\\usepackage[default]{raleway}

\\usepackage[
  a4paper,
  top=0pt, bottom=0.6cm,
  left=0pt, right=0pt,
  headheight=0pt, headsep=0pt
]{geometry}

\\usepackage{xcolor}
\\definecolor{headerBG}  {HTML}{2C3E50}
\\definecolor{headerFG}  {HTML}{FFFFFF}
\\definecolor{subtitleFG}{HTML}{BDC3C7}
\\definecolor{accentColor}{HTML}{2980B9}
\\definecolor{ruleColor} {HTML}{2980B9}
\\definecolor{bodyColor} {HTML}{1C1C1C}
\\definecolor{dateColor} {HTML}{666666}

\\usepackage{graphicx}
\\usepackage{tikz}
\\usetikzlibrary{calc}
\\usepackage{array,tabularx}
\\usepackage{fontawesome5}
\\usepackage[hidelinks]{hyperref}
\\hypersetup{colorlinks=true, urlcolor=black, linkcolor=black}

\\usepackage{enumitem}
\\setlist[itemize]{
  label={\\textcolor{accentColor}{\\tiny\\faCircle}},
  leftmargin=1.4em,
  itemsep=1pt, parsep=0pt, topsep=2pt, partopsep=0pt
}

\\usepackage{microtype}
\\pagestyle{empty}
\\setlength{\\parindent}{0pt}
\\setlength{\\parskip}{0pt}
\\linespread{0.95}

\\newcommand{\\profilephoto}[2][2.35cm]{%
  \\begin{tikzpicture}
    \\draw[accentColor, line width=2pt] (0,0) circle (#1/2);
    \\clip (0,0) circle (#1/2 - 1pt);
    \\node[inner sep=0pt] at (0,0)
      {\\includegraphics[height=#1,keepaspectratio=false]{#2}};
  \\end{tikzpicture}%
}

\\newcommand{\\hitem}[2]{%
  {\\color{headerFG}\\small#1}\\enspace{\\color{headerFG}\\small#2}%
}

\\newcommand{\\cvsec}[2]{%
  \\vspace{5pt}%
  \\noindent{\\color{accentColor}#1}\\enspace
  {\\fontsize{10}{12}\\selectfont\\bfseries\\color{headerBG}\\MakeUppercase{#2}}%
  \\par\\vspace{-7pt}%
  \\noindent{\\color{ruleColor}\\rule{\\linewidth}{1pt}}%
  \\par\\vspace{2pt}%
}

\\newcommand{\\entryrow}[2]{%
  \\noindent
  \\begin{tabularx}{\\linewidth}{@{}X r@{}}
    #1 & {\\footnotesize\\color{dateColor}#2}
  \\end{tabularx}%
  \\par\\vspace{-1pt}%
}`;

const beginDocMatch = latexCode.match(/(\\begin\{document\}[\s\S]*)/);
if (beginDocMatch) {
    latexCode = knownGoodPreamble + '\n\n' + beginDocMatch[1];
}

// ─── FIX 3: Extract contact block ───────────────────────────
// Stop strictly at \end{minipage} — never capture beyond the
// last hitem. The \end{minipage}%  line was being swallowed
// by the previous greedy regex, causing an extra closing tag.
const contactMatch = latexCode.match(
    /(\\hitem\{\\faEnvelope[\s\S]*?\\hitem\{\\faGithub\}[^\n]*\n?)(?:\s*\\end\{minipage\})/
);
const contactBlock = contactMatch
    ? contactMatch[1].trim()
    : `\\hitem{\\faEnvelope}{\\href{mailto:fathimk666@gmail.com}{fathimk666@gmail.com}}%
    \\hspace{12pt}%
    \\hitem{\\faPhone}{+49 155 1171 2618}%
    \\hspace{12pt}%
    \\hitem{\\faMapMarker*}{Passau, Germany}%
    \\par\\vspace{4pt}%
    \\hitem{\\faLinkedin}{\\href{https://linkedin.com/in/fathi-belmkadem}{in/fathi-belmkadem}}%
    \\hspace{12pt}%
    \\hitem{\\faGithub}{\\href{https://github.com/fathi-belmkadem}{github.com/fathi-belmkadem}}`;

// ─── FIX 4: Replace entire header + start of body ───────────
// Match from \begin{document} all the way through to just before
// the body content minipage. Replaces everything in between with
// our known-good header, regardless of what the AI generated.
const goodHeader = `\\color{bodyColor}

% HEADER
\\begin{tikzpicture}[remember picture, overlay]
  \\fill[headerBG]
    (current page.north west)
    rectangle
    ([yshift=-3.4cm] current page.north east);
\\end{tikzpicture}

\\noindent\\hspace{0.75cm}%
\\begin{minipage}[c][3.4cm][c]{\\dimexpr\\paperwidth - 1.5cm\\relax}
  \\begin{minipage}[c]{2.6cm}
    \\profilephoto[2.4cm]{profile.jpg}
  \\end{minipage}%
  \\hspace{0.3cm}%
  \\begin{minipage}[c]{\\dimexpr\\linewidth - 2.9cm\\relax}
    {\\fontsize{22}{26}\\selectfont\\bfseries\\color{headerFG}Fathi BELMKADEM}%
    \\par\\vspace{2pt}%
    {\\fontsize{10}{13}\\selectfont\\color{subtitleFG}\\textit{${jobTitle}}}%
    \\par\\vspace{9pt}%
    ${contactBlock}
  \\end{minipage}%
\\end{minipage}

\\vspace{0.3cm}

% BODY
\\noindent\\hspace{0.9cm}%
\\begin{minipage}{\\dimexpr\\paperwidth - 1.8cm\\relax}`;

// Replace everything from \begin{document} up to and including
// the body \begin{minipage} opening line
latexCode = latexCode.replace(
    /\\begin\{document\}[\s\S]*?\\begin\{minipage\}\{\\dimexpr\\paperwidth\s*-[^}]+\}/,
    `\\begin{document}\n${goodHeader}`
);

// ─── FIX 5: Unicode quotes ────────────────────────────────────
latexCode = latexCode.replace(/[""]/g, '"').replace(/['']/g, "'");

// ─── FIX 6: Fix \% in macro opening braces ───────────────────
latexCode = latexCode.replace(/\{\\%/g, '{%');

// ─── FIX 7: % escaping — line by line ────────────────────────
latexCode = latexCode.split('\n').map(line => {
    if (/^\s*%/.test(line)) return line;
    return line.replace(/([a-zA-Z0-9])%(?!%)/g, '$1\\%');
}).join('\n');

// ─── FIX 8: Ampersand — smart two-pass ───────────────────────
latexCode = latexCode.replace(/(?<!\\)&/g, '\\&');
latexCode = latexCode.replace(
    /(\\begin\{tabularx\}[\s\S]*?\\end\{tabularx\})/g,
    (block) => block.replace(/(\s|})\\&(\s|\{|\\)/g, '$1&$2')
);

// ─── FIX 9: Clamp vspace ─────────────────────────────────────
latexCode = latexCode.replace(/\\vspace\{(\d+(?:\.\d+)?)(pt)\}/g, (_, val) =>
    `\\vspace{${Math.min(parseFloat(val), 8)}pt}`
);
latexCode = latexCode.replace(/\\vspace\{(\d+(?:\.\d+)?)(cm)\}/g, (_, val) =>
    `\\vspace{${Math.min(parseFloat(val), 0.25)}cm}`
);

// ─── FIX 10: Force itemize spacing ───────────────────────────
latexCode = latexCode.replace(
    /\\begin\{itemize\}(\[[^\]]*\])?/g,
    '\\begin{itemize}[leftmargin=1.4em, itemsep=1pt, parsep=0pt, topsep=2pt, partopsep=0pt]'
);

// ─── FIX 11: Remove packages that crash XeLaTeX ──────────────
[
    /\\usepackage\[T1\]\{fontenc\}\n?/g,
    /\\usepackage\[utf8\]\{inputenc\}\n?/g,
    /\\usepackage\{fontspec\}\n?/g,
    /\\usepackage\{helvet\}\n?/g,
    /\\renewcommand\{\\familydefault\}\{\\sfdefault\}\n?/g,
    /\\setmainfont\{[^}]+\}\n?/g,
    /\\IfFontExistsTF\{[^}]+\}\{[^}]+\}\{[^}]+\}\n?/g,
    /\\faExternalLink\*/g,
].forEach(rx => { latexCode = latexCode.replace(rx, ''); });

return { json: { latex_code: latexCode } };

const coverUpload = $('Upload Cover Letter').first();
const cvUpload = $('Upload CV').first();
const hiringMessage = $('Inject Content').first().json.hiring_message;
const folder = $('Create Folder').first();

const coverBinary = $('Compile PDF').first().binary;
const cvBinary = $('Compile CV PDF').first().binary;

let response = {
  status: "success",
  message: "Application documents generated successfully!",
  folder_link: folder.json.webViewLink,
  cover_letter: { drive_link: coverUpload.json.webViewLink, file_name: "Motivation-Letter-Fathi-BELMKADEM.pdf" },
  cv: { drive_link: cvUpload.json.webViewLink, file_name: "CV-Fathi-BELMKADEM-Tailored.pdf" },
  hiring_message: hiringMessage
};

if (coverBinary && coverBinary.data) { response.cover_letter.base64_content = coverBinary.data.data; }
if (cvBinary && cvBinary.data) { response.cv.base64_content = cvBinary.data.data; }

return [{ json: response }];

// 1. Safety Check: Ensure the input exists to avoid "Referenced node doesn't exist"
if (!$input.first() || !$input.first().json.content) {
  throw new Error("No response received from the AI node.");
}

const responseString = $input.first().json.content.parts[0].text;

/**
 * EXTRACTION LOGIC
 * We use Regex to pull content between our custom tags. 
 * This is much safer than JSON.parse for LaTeX.
 */
function extractBetween(str, startTag, endTag) {
  const startIndex = str.indexOf(startTag) + startTag.length;
  const endIndex = str.indexOf(endTag);
  if (str.indexOf(startTag) === -1 || endIndex === -1) return null;
  return str.substring(startIndex, endIndex).trim();
}

let latex = extractBetween(responseString, "[LATEX_START]", "[LATEX_END]");
let email = extractBetween(responseString, "[HIRING_EMAIL_START]", "[HIRING_EMAIL_END]");

// Fallback if the AI fails to use tags
if (!latex) {
    // If tags fail, try to find a code block
    latex = responseString.match(/\\documentclass[\s\S]*\\end\{document\}/g)?.[0] || "Extraction Failed";
}

/**
 * REPAIR LOGIC
 */
if (latex !== "Extraction Failed") {
  // FIX 1: The Bracket Collision (Crucial for LaTeX compilers)
  // Finds any \\ followed by [ and inserts {} to break the link.
  latex = latex.replace(/\\\\(\s*)\[/g, '\\\\$1{}[');

  // FIX 2: Empty Line Break Error
  latex = latex.replace(/(\\begin\{[a-z*]+\})(\s*)\\\\/gi, '$1');
}

return {
  latex_code: latex,
  hiring_message: email || "Email extraction failed."
};

