return items.map(item => {
  // 1. GET INPUT
  // We access the 'data' field from the current item
  let rawText = item.json.data || "";

  // 2. CLEANING LOGIC

  // Remove the "cleaned text = empty" artifact
  let cleaned = rawText.replace(/cleaned text = empty/gi, '');

  // Replace literal string "\n" with actual new lines
  cleaned = cleaned.replace(/\\n/g, '\n');

  // Replace literal string "\t" with actual tabs
  cleaned = cleaned.replace(/\\t/g, '\t');

  // Remove surrounding quotes if present (e.g. " \documentclass... ")
  if (cleaned.startsWith('"') && cleaned.endsWith('"')) {
    cleaned = cleaned.slice(1, -1);
  }

  // Final trim to remove extra whitespace at start/end
  cleaned = cleaned.trim();

  // 3. OUTPUT
  // Return ONLY the variable 'latex_code' (this removes other fields)
  return {
    json: {
      latex_code: cleaned
    }
  };
});
